import{_ as e,o as s,c as i,a0 as t}from"./chunks/framework.DQOulFGV.js";const m=JSON.parse('{"title":"Mamba Cloud (PaaS)","description":"","frontmatter":{},"headers":[],"relativePath":"mamba-cloud.md","filePath":"mamba-cloud.md"}'),l={name:"mamba-cloud.md"};function o(n,a,p,d,h,r){return s(),i("div",null,[...a[0]||(a[0]=[t(`<h1 id="mamba-cloud-paas" tabindex="-1">Mamba Cloud (PaaS) <a class="header-anchor" href="#mamba-cloud-paas" aria-label="Permalink to &quot;Mamba Cloud (PaaS)&quot;">​</a></h1><p>Mamba 0.3.0 transforms the compiler into a complete Developer-to-Deployment Ecosystem via Mamba Cloud.</p><h2 id="instant-deployment" tabindex="-1">Instant Deployment <a class="header-anchor" href="#instant-deployment" aria-label="Permalink to &quot;Instant Deployment&quot;">​</a></h2><p>The Mamba Cloud engine allows you to deploy applications instantly to a local runtime environment.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./mamba</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8080</span></span></code></pre></div><p><em>This command automatically compiles the native C++ binary, daemonizes it, and maps it to the given port.</em></p><h2 id="multi-language-detection" tabindex="-1">Multi-Language Detection <a class="header-anchor" href="#multi-language-detection" aria-label="Permalink to &quot;Multi-Language Detection&quot;">​</a></h2><p>Mamba Cloud does not only run <code>.mb</code> files. It auto-detects and deploys:</p><ul><li><strong>Mamba Native C++</strong></li><li><strong>Node.js</strong> (<code>package.json</code>)</li><li><strong>Python</strong> (<code>app.py</code> or <code>requirements.txt</code>)</li></ul><h2 id="the-reverse-proxy-gateway" tabindex="-1">The Reverse Proxy Gateway <a class="header-anchor" href="#the-reverse-proxy-gateway" aria-label="Permalink to &quot;The Reverse Proxy Gateway&quot;">​</a></h2><p>Mamba Cloud includes a built-in routing gateway to manage active deployments using custom Virtual Hosts (<code>.mamba.local</code>).</p><p>Start the gateway:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./mamba</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> proxy</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8000</span></span></code></pre></div><p>This enables zero-config local domains (e.g., <code>http://my-api.mamba.local:8000</code>).</p><h2 id="bare-git-auto-deploy-server" tabindex="-1">Bare Git Auto-Deploy Server <a class="header-anchor" href="#bare-git-auto-deploy-server" aria-label="Permalink to &quot;Bare Git Auto-Deploy Server&quot;">​</a></h2><p>You can configure a Git repository to automatically deploy code directly via <code>git push</code>.</p><ol><li>Initialize the deployment server:<div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./mamba</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> git-init</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my_api</span></span></code></pre></div></li><li>Add the remote and push:<div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> remote</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mamba_cloud</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ../mamba_cloud_repos/my_api.git</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> push</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mamba_cloud</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> main</span></span></code></pre></div></li></ol><p><em>Upon push, Mamba intercepts the hook, natively compiles the C++ codebase, and orchestrates a zero-downtime swap of the running processes.</em></p><h2 id="global-edge-bridges" tabindex="-1">Global Edge Bridges <a class="header-anchor" href="#global-edge-bridges" aria-label="Permalink to &quot;Global Edge Bridges&quot;">​</a></h2><p>Instantly expose your local deployments to the global internet via integrated tunneling (e.g., Cloudflare).</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./mamba</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8081</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --public</span></span></code></pre></div>`,21)])])}const g=e(l,[["render",o]]);export{m as __pageData,g as default};
